  ["13bc2b2d"] = "Принесіть «Heart of the Mountain» до НІП «{npc:Maxwort Uberglint}» у локації «{zone:Burning Steppes}».",
  ["5a24a7ac"] = "Предмет «{item:The Heart of the Mountain}» лежить у сейфі сховища після Темних хранителів.",
  ["5681a0d7"] = "Принесіть «{item:Star Ruby}»: 2 шт., «{item:Gold Bar}»: 20 шт. і «{item:Truesilver Bar}»: 10 шт. до НІП «{npc:Gloom'rel}», потім покладіть їх у «Spectral Chalice» у місцевості «{zone:Summoners' Tomb}».",
  ["c6ac55db"] = "Гірнича справа 230. Поговоріть з НІП «{npc:Gloom'rel}» перед боєм із «The Seven»; покладіть у «Spectral Chalice» «{item:Star Ruby}»: 2 шт., «{item:Gold Bar}»: 20 шт. і «{item:Truesilver Bar}»: 10 шт., щоб вивчити «Smelt Dark Iron».",
  ["18ce8f88"] = "Поговоріть з НІП «{npc:Yuka Screwspigot}» у локації «{zone:Burning Steppes}».",
  ["b2c863ba"] = "Вступний крок до завдання «{quest:Ribbly Screwspigot}».",
  ["bfef45bd"] = "Принесіть предмет «{item:Ribbly's Head}» до НІП «{npc:Yuka Screwspigot}» у локації «{zone:Burning Steppes}».",
  ["fedaedea"] = "Принесіть «Gromsblood»: 4 шт., «{item:Giant Silver Vein}»: 10 шт. і предмет «{item:Nagmara's Filled Vial}» до НІП «{npc:Mistress Nagmara}» у підземеллі «{zone:Blackrock Depths}».",
  ["3ab99969"] = "Кров Ґрома, велетенські срібні жили (скельні велетні в локації «{zone:Azshara}») і фіал, наповнений у місцевості «{zone:Golakka Hot Springs}» у Кратері Ун'Ґоро. Відкриває мирний прохід через бар під час наступних відвідин.",
  ["ac4c8908"] = "Поговоріть з НІП «{npc:Ragnar Thunderbrew}».",
  ["3b1ef548"] = "Вступний крок до завдання «{quest:Hurley Blackbreath}».",
  ["1d62a960"] = "Принесіть предмет «{item:Lost Thunderbrew Recipe}» до НІП «{npc:Ragnar Thunderbrew}» у місцевості «{zone:Kharanos}».",
  ["700ee3f0"] = "Розбийте три бочонки в коморі місцевості «{zone:The Grim Guzzler}», щоб з’явилися НІП «{npc:Hurley Blackbreath}» і його охоронці.\n\nНеобов’язкове вступне завдання:",
  ["2e60650b"] = "Поговоріть з НІП «{npc:Shadowmage Vivian Lagrave}» у місцевості «{zone:Kargath}».",
  ["3824bc40"] = "Вступний крок до завдання «{quest:Lost Thunderbrew Recipe}».",
  ["3e40eef5"] = "Принесіть предмет «{item:Lost Thunderbrew Recipe}» до НІП «Вівіан Лаґрейв» у місцевості «{zone:Kargath}».",
  ["eb9e5060"] = "Знайдіть НІП «{npc:Lord Incendius}» у підземеллі «{zone:Blackrock Depths}» і знищте його!",
  ["4f8a26d3"] = "Убийте боса «{npc:Lord Incendius}» біля «Black Anvil» у Глибинах Блекрок.",
  ["4ec34ffa"] = "Увійдіть до підземелля «{zone:Blackrock Depths}» і вистежте НІП «{npc:Lord Incendius}». Убийте його й принесіть до НІП «{npc:Thunderheart}» усі джерела відомостей, які знайдете.",
  ["bddbf95e"] = "Убийте боса «{npc:Lord Incendius}» біля «Black Anvil» у Глибинах Блекрок і принесіть предмет «{item:Tablet of Kurniya}».",
  ["5b02e249"] = "Вирушайте до підземелля «{zone:Blackrock Depths}» і здобудьте «{item:Essence of the Elements}»: 10 шт. Спершу варто обшукати големів і їхніх творців. Ви пам’ятаєте, що Вівіан Лаґрейв також бурмотіла щось про елементалів.",
  ["e4980264"] = "Предмет «{item:Essence of the Elements}» випадає з елементалів і големів у Глибинах Блекрок.",
  ["1999badd"] = "Допоможіть НІП «{npc:Marshal Windsor}» повернути спорядження та звільнити друзів. У разі успіху поверніться до НІП «{npc:Marshal Maxwell}».",
  ["9798e3e8"] = "Супроводьте НІП «{npc:Marshal Windsor}» через в’язницю. Спершу зачистіть патрулі й переконайтеся, що всі готові, перш ніж почати.",
  ["5f1b3a6f"] = "Захистіть командира Ґор’шака.",
  ["87fea959"] = "Відчиніть його камеру предметом «{item:Prison Cell Key}» від НІП «{npc:High Interrogator Gerstahn}», а потім захистіть його.",
  ["947f71fa"] = "Знайдіть і вбийте боса «{npc:Golem Lord Argelmach}». Принесіть його голову до Лотвіла. Також потрібно зібрати «{item:Intact Elemental Core}»: 10 шт. з големів-шаленців і конструктів-войовників, що охороняють Арґельмаха.",
  ["67d47031"] = "Убийте боса «{npc:Golem Lord Argelmach}» заради його голови й зберіть «{item:Intact Elemental Core}»: 10 шт. з конструктів, що його охороняють.",
  ["5edf9d54"] = "Вирушайте до підземелля «{zone:Blackrock Depths}» і знищте мерзенних загарбників! НІП «{npc:Warlord Goretooth}» хоче, щоб ви вбили «{npc:Anvilrage Guardsman}»: 15, «{npc:Anvilrage Warden}»: 10 і «{npc:Anvilrage Footman}»: 5. Виконавши завдання, поверніться до нього.",
  ["ba87c074"] = "Вирушайте до підземелля «{zone:Blackrock Depths}» і знищте мерзенних загарбників! НІП «{npc:Warlord Goretooth}» хоче, щоб ви вбили «{npc:Anvilrage Medic}»: 10, «{npc:Anvilrage Soldier}»: 10 і «{npc:Anvilrage Officer}»: 10. Виконавши завдання, поверніться до нього.",
  ["5fbf9fb7"] = "Вирушайте до підземелля «{zone:Blackrock Depths}» і вбийте боса «{npc:General Angerforge}»! Виконавши завдання, поверніться до НІП «{npc:Warlord Goretooth}».",
  ["f4def4c0"] = "Спершу потрібні обидва завдання «KILL ON SIGHT» і супровід НІП «{npc:Grark Lorkrub}».",
  ["df6c8b66"] = "Вирушайте до підземелля «{zone:Blackrock Depths}» і вбийте боса «{npc:Bael'Gar}». Використайте предмет «{item:Altered Black Dragonflight Molt}» на рештках боса «{npc:Bael'Gar}», щоб уловити «Fiery Essence». Принесіть предмет «{item:Encased Fiery Essence}» до НІП «{npc:Cyrus Therepentous}».",
  ["a608498f"] = "Поверніться до підземелля «{zone:Blackrock Depths}» і врятуйте НІП «{npc:Princess Moira Bronzebeard}» з лихих пазурів НІП «{npc:Emperor Dagran Thaurissan}».",
  ["62f3a5b7"] = "Не дайте принцесі Мойрі загинути й поговоріть із нею після смерті імператора Даґрана Тауріссана. Її завдання «The Princess's Surprise» відправить вас по нагороду назад до Маґні.",
  ["a967f5bf"] = "Убийте боса «{npc:Emperor Dagran Thaurissan}» і звільніть НІП «{npc:Princess Moira Bronzebeard}» від його лихих чарів.",
  ["cb34492d"] = "Не дайте принцесі Мойрі загинути й поговоріть із нею після смерті імператора Даґрана Тауріссана. Її завдання «The Princess Saved?» відправить вас по нагороду назад до НІП «{npc:Thrall}».",
  ["e402aece"] = "Вирушайте до підземелля «{zone:Blackrock Depths}» і здобудьте «{item:Dark Iron Fanny Pack}»: 20 шт. Виконавши це, поверніться до НІП «{npc:Oralius}». Ви припускаєте, що ці «поясні сумки» носять дворфи Темного Заліза в підземеллі «{zone:Blackrock Depths}».",
  ["87ccd849"] = "«Dark Iron Fanny Packs» випадають із дворфів Темного Заліза в Глибинах Блекрок.",
  ["35e85f85"] = "Вирушайте до порталу в рейд «{zone:Molten Core}» у підземеллі «{zone:Blackrock Depths}» і здобудьте предмет «{item:Core Fragment}». Здобувши предмет «{item:Core Fragment}», поверніться до НІП «{npc:Lothos Riftwaker}» у місцевості «{zone:Blackrock Mountain}».",
  ["3fc0f20d"] = "Предмет «{item:Core Fragment}» лежить на камені біля порталу в рейд «{zone:Molten Core}» далеко в Глибинах Блекрок. Відкриває телепорт від Лотоса в рейд «{zone:Molten Core}».",
  ["7af16034"] = "Здайте предмет «{item:Thorium Brotherhood Contract}» НІП «{npc:Lokhtos Darkbargainer}», якщо хочете отримати креслення Сульфуронового молота.",
  ["9e2451d0"] = "Ковальство. Принесіть предмет «{item:Sulfuron Ingot}» (бос «Golemagg», рейд «{zone:Molten Core}») до НІП «Lokhtos» у місцевості «{zone:The Grim Guzzler}», щоб отримати контракт, а потім здайте його назад за креслення «{item:Sulfuron Hammer}».",
  ["31e0b7de"] = "Вирушайте до місцевості «{zone:Ruins of Thaurissan}» («{zone:Burning Steppes}») і зберіть відомості з «Thaurissan Relics». Зібравши їх, поверніться до НІП «{npc:Royal Historian Archesonus}».",
  ["b68cb47f"] = "Вислухайте, як НІП «{npc:Royal Historian Archesonus}» переказує історію Тауріссана.",
  ["b7af21dd"] = "Поговоріть з НІП «{npc:Franclorn Forgewright}», якщо хочете отримати ключ від міста.",
  ["4ed68c6c"] = "Щоб поговорити з ним, треба бути мертвим. Він у місцевості «{zone:Blackrock Mountain}», у кімнаті на шляху ланцюгом униз до Глибин Блекрок.",
  ["ad7d19e3"] = "Вирушайте до каменоломні в місцевості «{zone:Blackrock Mountain}» і вбийте боса «{npc:Overmaster Pyron}». Виконавши доручення, поверніться до НІП «{npc:Thunderheart}».",
  ["efd023fa"] = "Знайдіть НІП «{npc:Commander Gor'shak}» у підземеллі «{zone:Blackrock Depths}». Ви пам’ятаєте, що на грубо намальованому портреті орка були ґрати. Можливо, варто пошукати якусь в’язницю.",
  ["c0ec53ca"] = "Поговоріть з НІП «{npc:Kharan Mighthammer}» і дізнайтеся про викрадення НІП «{npc:Princess Moira Bronzebeard}». Передайте ці відомості НІП «{npc:Thrall}» у місті «{zone:Orgrimmar}». Ви пам’ятаєте, як командир Ґор’шак казав, що Карана тримають у камері неподалік.",
  ["b6854794"] = "Поговоріть з НІП «{npc:Thrall}», якщо готові взятися за задуману ним місію.",
  ["1f11c3db"] = "Вирушайте до локації «{zone:Burning Steppes}» і здобудьте «{item:Fractured Elemental Shard}»: 10 шт. для НІП «{npc:Hierophant Theodora Mulvadania}». Ви пам’ятаєте, що, за словами Теодори, ці уламки можна добути з големів і елементалів того краю.",
  ["c28d4980"] = "Віднесіть предмет «{item:Elemental Shard Sample}» до НІП «{npc:Lotwil Veriatus}». Ви пам’ятаєте, що, за словами Теодори, Лотвіл стоїть табором на сході.",
  ["5e535bed"] = "Супроводьте свого в’язня, НІП «{npc:Grark Lorkrub}», через локації «{zone:Burning Steppes}» і «{zone:Blackrock Mountain}» до локації «{zone:Searing Gorge}». Ви пам’ятаєте, як НІП «{npc:Lexlort}» казав, що його люди чекатимуть на тому боці, щоб узяти Ґрарка під варту. Також потрібно буде віддати предмет «{item:Thorium Shackles}» НІП «{npc:Lexlort}».",
  ["649e13be"] = "Вирушайте до локації «{zone:Burning Steppes}» і знайдіть НІП «{npc:Grark Lorkrub}». Ви пам’ятаєте, як НІП «{npc:Lexlort}» казав, що востаннє його бачили у величезній фортеці Блекрок. Знайшовши НІП «{npc:Grark Lorkrub}», скуйте його предметом «{item:Thorium Shackles}» і відведіть через місцевість «{zone:Blackrock Mountain}» до локації «{zone:Searing Gorge}». НІП «{npc:Lexlort}» чекатиме з людьми на тому боці, щоб узяти Ґрарка під варту.",
  ["574ed63d"] = "Убийте «{npc:Black Broodling}»: 15, «{npc:Black Dragonspawn}»: 10, «{npc:Black Wyrmkin}»: 4 і «{npc:Black Drake}»: 1. Виконавши завдання, поверніться до НІП «{npc:Helendis Riverhorn}».",
  ["94ea9dea"] = "Вирушайте до місцевості «{zone:Lakeshire}» і доставте предмет «{item:Helendis Riverhorn's Letter}» до НІП «{npc:Magistrate Solomon}».",
  ["1ab47e8e"] = "Вирушайте до міста «{zone:Stormwind}» і доставте «Solomon's Plea» до НІП «{npc:Highlord Bolvar Fordragon}». Болвар перебуває в місцевості «{zone:Stormwind Keep}».",
  ["36792697"] = "Поговоріть з НІП «{npc:Highlord Bolvar Fordragon}» після розмови з НІП «{npc:Lady Katrana Prestor}».",
  ["da96696a"] = "Віднесіть предмет «{item:Bolvar's Decree}» до НІП «{npc:Magistrate Solomon}» у місцевості «{zone:Lakeshire}».",
  ["3cc63c16"] = "Поговоріть з НІП «{npc:Marshal Maxwell}» у локації «{zone:Burning Steppes}».",
  ["cdf10411"] = "Поговоріть з НІП «{npc:Ragged John}», щоб дізнатися про долю НІП «{npc:Marshal Windsor}», а потім поверніться до НІП «{npc:Marshal Maxwell}». Ви пам’ятаєте, як НІП «{npc:Marshal Maxwell}» радив шукати його в печері на півночі.",
  ["ddfca6d0"] = "Вирушайте до місцевості «{zone:Blackrock Mountain}» на північному заході й увійдіть до підземелля «{zone:Blackrock Depths}». З’ясуйте, що сталося з НІП «{npc:Marshal Windsor}». Ви пам’ятаєте, як НІП «{npc:Ragged John}» розповідав, що Віндзора потягли до в’язниці.",
  ["3c948345"] = "Повідомте НІП «{npc:Marshal Maxwell}» погану новину.",
  ["490e7b2a"] = "Убийте боса «{npc:Overmaster Pyron}» і поверніться до НІП «{npc:Jalinda Sprig}». Ви пам’ятаєте, як Джалінда казала, що Пайрон охороняє каменоломню. Може, варто пошукати там?",
  ["9bf77380"] = "Схоже, ви натрапили на щось, що НІП «{npc:Marshal Windsor}» захоче побачити. Можливо, надія все ж є.",
  ["df599839"] = "Поверніть предмет «{item:Marshal Windsor's Lost Information}». НІП «{npc:Marshal Windsor}» вважає, що ці відомості зберігаються в босів «{npc:Golem Lord Argelmach}» і «{npc:General Angerforge}».",
  ["633ca92d"] = "Вирушайте до підземелля «{zone:Blackrock Depths}» і знайдіть НІП «{npc:Kharan Mighthammer}». Король згадував, що Карана тримають там у полоні, — можливо, варто пошукати в’язницю.",
  ["6ea61767"] = "Вислухайте розповідь НІП «{npc:Kharan Mighthammer}».",
  ["32bcb16a"] = "Поверніться до міста «{zone:Ironforge}» і повідомте погану новину НІП «{npc:King Magni Bronzebeard}».",
  ["338a1d87"] = "Поговоріть із НІП «Rugged Traveler».",
  ["014f15e9"] = "Перейдіть мостом, що трохи на схід від «Ring of Law» і веде на північ над лавою, та зачистіть його. З лівого боку, біля невеликої жаровні, зістрибніть із перил на платформу біля стіни, дійдіть нею до кута і тримайтеся лівим плечем стіни, доки не зістрибнете на кам’яний виступ внизу: там стоїть НІП «Rugged Traveler». Двері на виступі ведуть на виступ над НІП «{npc:Lord Incendius}»; дороги назад немає. Не можна поділитися.",
}
